import React from 'react';

export default function Hero({ setCurrentPage }) {
  return (
    <div style={{
      position: 'relative',
      padding: '110px 20px',
      textAlign: 'center',
      color: '#ffffff',
      backgroundImage: `linear-gradient(rgba(15, 23, 42, 0.85), rgba(30, 58, 138, 0.88)), url('https://images.unsplash.com/photo-1523240795612-9a054b0db644?q=80&w=1600&auto=format&fit=crop')`,
      backgroundSize: 'cover',
      backgroundPosition: 'center',
      boxShadow: '0 10px 30px rgba(0,0,0,0.15)'
    }}>
      <div style={{ maxWidth: '850px', margin: '0 auto' }}>
        <span style={{
          backgroundColor: 'rgba(255, 255, 255, 0.15)',
          color: '#38bdf8',
          padding: '6px 20px',
          borderRadius: '20px',
          fontSize: '13px',
          fontWeight: 'bold',
          letterSpacing: '1px',
          display: 'inline-block',
          marginBottom: '20px',
          backdropFilter: 'blur(5px)',
          border: '1px solid rgba(255, 255, 255, 0.2)'
        }}>
          🎓 EXCELLENCE IN SECONDARY & HIGHER EDUCATION
        </span>

        <h1 style={{ fontSize: '48px', marginBottom: '20px', fontWeight: '800', lineHeight: '1.2' }}>
          AuraPen Saku Education Institute
        </h1>
        
        <p style={{ fontSize: '18px', marginBottom: '40px', color: '#e2e8f0', maxWidth: '680px', margin: '0 auto 40px auto', lineHeight: '1.7' }}>
          Shaping academic futures through structured guidance, expert faculty, and modern digital learning tools. Explore our physical and digital class modules today.
        </p>

        <div style={{ display: 'flex', justifyContent: 'center', gap: '15px', flexWrap: 'wrap' }}>
          <button 
            onClick={() => setCurrentPage('Classes')}
            style={{
              padding: '14px 32px', fontSize: '16px', fontWeight: 'bold', color: '#0f172a', backgroundColor: '#ffffff',
              border: 'none', borderRadius: '30px', cursor: 'pointer', transition: '0.3s', boxShadow: '0 4px 15px rgba(0,0,0,0.2)'
            }}
          >
            📚 Explore Courses
          </button>
          
          <button 
            onClick={() => setCurrentPage('Contact')}
            style={{
              padding: '14px 32px', fontSize: '16px', fontWeight: 'bold', color: '#ffffff', backgroundColor: 'transparent',
              border: '2px solid #ffffff', borderRadius: '30px', cursor: 'pointer', transition: '0.3s'
            }}
          >
            📞 Contact Us
          </button>
        </div>
      </div>
    </div>
  );
}
